function kodeBahasaPrompt() {
  try {
    const lang = String(useStore.getState().settings?.general?.uiLang || "en");
    return lang.toLowerCase().slice(0, 2) || "en";
  } catch {
    return "en";
  }
}
function perBahasa(tabel, inggris) {
  return tabel[kodeBahasaPrompt()] ?? inggris;
}
